#!/usr/bin/env bash
set -Eeuo pipefail

SERVER="192.168.1.123"
REMOTE_USER="matin"
TS="$(date +%Y%m%d-%H%M%S)"
DOWNLOAD_DIR="$HOME/Downloads"
LOCAL_REPORT="$DOWNLOAD_DIR/pulsar-reference-good-port-$TS.log"
SOCKET="/tmp/pulsar-reference-good-${USER}-$$"
LOCAL_PAYLOAD="/tmp/pulsar-reference-good-payload.tar.gz"
LOCAL_REMOTE_SCRIPT="/tmp/pulsar-reference-good-remote-install.sh"
REMOTE_PAYLOAD="/tmp/pulsar-reference-good-payload.tar.gz"
REMOTE_SCRIPT="/tmp/pulsar-reference-good-remote-install.sh"

mkdir -p "$DOWNLOAD_DIR"

if [[ "$(hostname -s 2>/dev/null || hostname)" == "pulsar" || "$(whoami)" == "matin" ]]; then
  echo "ERROR: این دستور را روی سیستم خودت اجرا کن، نه داخل سرور."
  echo "ابتدا exit بزن تا prompt دوباره amin@localhost شود."
  exit 1
fi

for command in ssh scp base64 tee; do
  command -v "$command" >/dev/null 2>&1 || {
    echo "ERROR: دستور $command روی سیستم شما نصب نیست."
    exit 1
  }
done

cleanup() {
  ssh -S "$SOCKET" -O exit "$REMOTE_USER@$SERVER" >/dev/null 2>&1 || true
  rm -f "$SOCKET" "$LOCAL_PAYLOAD" "$LOCAL_REMOTE_SCRIPT"
}
trap cleanup EXIT

cat > "$LOCAL_PAYLOAD.b64" <<'__PAYLOAD_B64__'

__PAYLOAD_B64__
base64 -d "$LOCAL_PAYLOAD.b64" > "$LOCAL_PAYLOAD"
rm -f "$LOCAL_PAYLOAD.b64"

cat > "$LOCAL_REMOTE_SCRIPT.b64" <<'__REMOTE_B64__'

__REMOTE_B64__
base64 -d "$LOCAL_REMOTE_SCRIPT.b64" > "$LOCAL_REMOTE_SCRIPT"
rm -f "$LOCAL_REMOTE_SCRIPT.b64"
chmod 700 "$LOCAL_REMOTE_SCRIPT"

EXPECTED_PAYLOAD_SHA="$(sha256sum "$LOCAL_PAYLOAD" | awk '{print $1}')"

echo "============================================================"
echo "Porting proven camera/render path to Pulsar"
echo "Local:  $(whoami)@$(hostname)"
echo "Server: $REMOTE_USER@$SERVER"
echo "Report: $LOCAL_REPORT"
echo "============================================================"
echo
echo "مرحله ۱: رمز SSH کاربر matin را وارد کن."

ssh   -M   -S "$SOCKET"   -o ControlPersist=600   -o StrictHostKeyChecking=accept-new   -o ServerAliveInterval=15   -o ServerAliveCountMax=6   -fnN   "$REMOTE_USER@$SERVER"

scp -o ControlPath="$SOCKET" "$LOCAL_PAYLOAD" "$REMOTE_USER@$SERVER:$REMOTE_PAYLOAD"
scp -o ControlPath="$SOCKET" "$LOCAL_REMOTE_SCRIPT" "$REMOTE_USER@$SERVER:$REMOTE_SCRIPT"

REMOTE_SHA="$(ssh -o ControlPath="$SOCKET" "$REMOTE_USER@$SERVER" "sha256sum '$REMOTE_PAYLOAD' | awk '{print \$1}'")"
if [[ "$REMOTE_SHA" != "$EXPECTED_PAYLOAD_SHA" ]]; then
  echo "ERROR: فایل مرجع در انتقال به سرور خراب شده است."
  exit 1
fi

echo
echo "مرحله ۲: اصلاح، Build و تست خودکار شروع می‌شود."
echo "اگر sudo رمز خواست، رمز کاربر matin را وارد کن؛ هنگام تایپ چیزی نمایش داده نمی‌شود."
echo

set +e
ssh   -tt   -o ControlPath="$SOCKET"   "$REMOTE_USER@$SERVER"   "bash '$REMOTE_SCRIPT'" 2>&1 | tee "$LOCAL_REPORT"
STATUS=${PIPESTATUS[0]}
set -e

REMOTE_REPORT="$(grep -E '^Report: /home/matin/pulsar-reference-good-report-' "$LOCAL_REPORT" | tail -n1 | sed 's/^Report: //')"
if [[ -n "$REMOTE_REPORT" ]]; then
  scp -o ControlPath="$SOCKET" "$REMOTE_USER@$SERVER:$REMOTE_REPORT" "$DOWNLOAD_DIR/" >/dev/null 2>&1 || true
fi

echo
echo "============================================================"
echo "گزارش روی سیستم خودت ذخیره شد:"
echo "$LOCAL_REPORT"
echo "============================================================"

if [[ "$STATUS" -ne 0 ]]; then
  echo "اصلاح کامل نشده و اسکریپت نسخه قبلی را Rollback کرده است."
  echo "همین فایل گزارش را ارسال کن."
  exit "$STATUS"
fi

if ! grep -q 'FINAL_STATUS=REFERENCE_GOOD_RUNNING_WITH_CUDA' "$LOCAL_REPORT"; then
  echo "ERROR: پیام موفقیت نهایی در گزارش پیدا نشد."
  echo "همین فایل گزارش را ارسال کن."
  exit 1
fi

echo "نسخه مرجع با کیفیت کامل و رندر تک‌مسیره با موفقیت روی سرور فعال شد."
